mapper.select:
SELECT * FROM ( SELECT a.*, ROWNUM AS rnum FROM ( SELECT faq_no AS faqNo, category, question, answer, sort_order AS sortOrder, delete_yn AS deleteYn, created_at AS createdAt FROM faq WHERE delete_yn = 'N'
AND category = #{category}
AND (question LIKE '%' || #{keyword} || '%' OR answer LIKE '%' || #{keyword} || '%')
ORDER BY category, sort_order ASC ) a WHERE ROWNUM <= #{endRow} ) WHERE rnum > #{startRow}

SELECT COUNT(*) FROM faq WHERE delete_yn = 'N'
AND category = #{category}
AND (question LIKE '%' || #{keyword} || '%' OR answer LIKE '%' || #{keyword} || '%')
